import type { DashboardFilters } from "@/lib/filters/schema";
import { fmtCalendarDate, fmtDate, fmtDuration, fmtInt, fmtPct, statusLabel } from "@/lib/format";
import type { ProjectSpike } from "./anomalies";
import type { CrossTab, FilterOptions, GroupMetrics, InsightRule, PeriodComparison, ProjectCoverage, RecurringSessions } from "./types";

/**
 * Deterministic management insights. Every statement is computed from the
 * supplied aggregates with thresholds an administrator can configure
 * (Settings → Thresholds); nothing is generated by an AI model and no cause is
 * asserted. Each insight says whether it is an observation, a recommendation
 * (an action grounded in the evidence) or a data caveat, carries its evidence,
 * explains its comparison method, and links to the view that reproduces it.
 * Insights are recomputed on every request, so they follow new imports and
 * disappear when their conditions no longer hold.
 */

export type InsightSeverity = "info" | "watch" | "attention";
export type InsightArea = "volume" | "trend" | "resolution" | "backlog" | "recurring" | "data";
export type InsightKind = "observation" | "recommendation" | "caveat";

export interface InsightLink {
  pathname: string;
  overrides?: Partial<DashboardFilters>;
  extra?: Record<string, string>;
  hash?: string;
  label: string;
}

export interface Insight {
  id: string;
  area: InsightArea;
  severity: InsightSeverity;
  kind: InsightKind;
  title: string;
  statement: string;
  /** Suggested next step (recommendations only). Never a claimed root cause. */
  recommendation?: string;
  /** How the figures were compared (periods, baselines, exclusions). */
  method?: string;
  evidence: { label: string; value: string }[];
  link?: InsightLink;
}

/** Defaults mirror the seeded insight_rules rows (used when a rule is missing). */
export const DEFAULT_RULES = {
  trend_window_days: 30,
  trend_min_current: 20,
  trend_min_change: 0.5,
  trend_min_z: 1.96,
  slow_topic_min_n: 30,
  slow_topic_factor: 1.25,
  dominant_theme_share: 0.4,
  dominant_theme_min_topic: 100,
  lesson_min_students: 50,
  recurring_min_students: 2,
  spike_window_days: 28,
  spike_threshold: 3.5,
  spike_min_count: 10,
  spike_rampup_days: 21,
  breach_watch_rate: 0.2,
  breach_attention_rate: 0.5,
  stale_export_days: 7,
  generic_ack_caveat_share: 0.5,
};

export type InsightRules = typeof DEFAULT_RULES;

export function rulesFrom(list: InsightRule[] | undefined): InsightRules {
  const out = { ...DEFAULT_RULES };
  for (const r of list ?? []) {
    if (r.key in out && Number.isFinite(Number(r.value))) (out as Record<string, number>)[r.key] = Number(r.value);
  }
  return out;
}

export interface DataHealth {
  coverage: ProjectCoverage[];
  activeImports: FilterOptions["active_imports"];
  partialImports: { project: string; rows_applied: number; rows_to_apply: number | null }[];
  rejectedRows: { project: string; rejected: number; source_filename: string }[];
  unmappedTopics: number;
  unclassifiedStatusTickets: number;
}

export interface InsightInputs {
  overall: GroupMetrics | null;
  projects: GroupMetrics[];
  topics: GroupMetrics[];
  topicPeriods: PeriodComparison | null;
  topicThemes: CrossTab | null;
  recurring: RecurringSessions | null;
  lessons?: GroupMetrics[];
  spikes: ProjectSpike[];
  subcategoryLabels: Record<string, string>;
  thresholds: { response_seconds: number; resolution_seconds: number };
  rules?: InsightRules;
  health?: DataHealth;
  projectNames?: Record<string, string>;
}

function share(part: number, whole: number): number | null {
  return whole > 0 ? part / whole : null;
}

/** Two-proportion z-score for a change of share between two periods. */
export function shareZ(cur: number, curTotal: number, prev: number, prevTotal: number): number | null {
  if (curTotal <= 0 || prevTotal <= 0) return null;
  const p = (cur + prev) / (curTotal + prevTotal);
  const se = Math.sqrt(p * (1 - p) * (1 / curTotal + 1 / prevTotal));
  if (!(se > 0)) return null;
  return (cur / curTotal - prev / prevTotal) / se;
}

const REASON_TEXT: Record<string, string> = {
  insufficient_history: "started within the comparison period",
  export_ends_before_period: "its export ends before the period",
  no_data: "no tickets",
};

/** Human description of the windows each project was compared over. */
export function describePeriods(p: PeriodComparison, names: Record<string, string> = {}): string {
  const label = (code: string) => names[code] ?? code;
  const included = p.projects.filter((x) => x.included);
  const excluded = p.projects.filter((x) => !x.included && x.reason !== "no_data");
  const range = (a: string | null, b: string | null) => `${fmtCalendarDate(a)} – ${fmtCalendarDate(b)}`;
  const parts: string[] = [];
  if (p.mode === "aligned") {
    const same = new Set(included.map((x) => x.current_to)).size <= 1;
    if (same && included[0]) {
      parts.push(`Latest ${p.days} complete days (${range(included[0].current_from, included[0].current_to)}) vs the preceding ${p.days} days (${range(included[0].previous_from, included[0].previous_to)}).`);
    } else {
      parts.push(
        `Each project is compared over its own latest ${p.days} complete days, because exports end on different dates: ${included
          .map((x) => `${label(x.project)} ${range(x.current_from, x.current_to)} vs ${range(x.previous_from, x.previous_to)}`)
          .join("; ")}.`,
      );
    }
  } else if (p.current && p.previous) {
    parts.push(`Selected period ${range(p.current.from, p.current.to)} vs the preceding ${p.days} days (${range(p.previous.from, p.previous.to)}).`);
  }
  if (excluded.length > 0) parts.push(`Not compared: ${excluded.map((x) => `${label(x.project)} (${REASON_TEXT[x.reason] ?? x.reason})`).join(", ")}.`);
  parts.push("Shares of all tickets are compared, so overall volume changes are accounted for.");
  return parts.join(" ");
}

const ORDER: Record<InsightSeverity, number> = { attention: 0, watch: 1, info: 2 };
const KIND_ORDER: Record<InsightKind, number> = { recommendation: 0, observation: 1, caveat: 2 };

export function buildInsights(input: InsightInputs): Insight[] {
  const R = input.rules ?? DEFAULT_RULES;
  const names = input.projectNames ?? Object.fromEntries(input.projects.map((p) => [p.key, p.label]));
  const out: Insight[] = [...dataCaveats(input, R, names)];
  const overall = input.overall;
  if (!overall || overall.tickets === 0) return out.sort(byPriority);

  // 1. Volume distribution (with relative activity) ---------------------------
  const projects = [...input.projects].sort((a, b) => b.tickets - a.tickets);
  if (projects.length > 1) {
    const top = projects[0];
    out.push({
      id: "volume-leader",
      area: "volume",
      severity: "info",
      kind: "observation",
      title: `${top.label} has the highest ticket volume`,
      statement: `${top.label} accounts for ${fmtPct(share(top.tickets, overall.tickets))} of tickets in the current view (${fmtInt(top.tickets)} of ${fmtInt(overall.tickets)}). Volume reflects each project's size and data coverage as well as its issues; compare tickets per student below.`,
      evidence: projects.map((p) => ({
        label: p.label,
        value: `${fmtInt(p.tickets)} (${fmtPct(share(p.tickets, overall.tickets))}) · ${p.unique_owners ? (p.tickets / p.unique_owners).toFixed(2) : "—"} per student`,
      })),
      link: { pathname: "/projects", label: "Compare projects" },
    });
  }

  // 2. Rising / falling topics (share of volume, per-project coverage) ---------
  const periods = input.topicPeriods;
  if (periods) {
    const totCur = periods.totals?.current ?? 0;
    const totPrev = periods.totals?.previous ?? 0;
    const method = describePeriods(periods, names);
    if (totCur === 0 || totPrev === 0) {
      if (periods.projects?.some((p) => p.reason === "insufficient_history" || p.reason === "export_ends_before_period")) {
        out.push({
          id: "trend-unavailable",
          area: "trend",
          severity: "info",
          kind: "caveat",
          title: "Topic trends cannot be compared for this selection",
          statement: "No project in view has complete data for both the latest and the preceding period, so a period-over-period comparison would be misleading.",
          method,
          evidence: periods.projects.map((p) => ({ label: names[p.project] ?? p.project, value: p.included ? "compared" : (REASON_TEXT[p.reason] ?? p.reason) })),
        });
      }
    } else {
      const rows = periods.rows
        .map((r) => {
          const curShare = r.current / totCur;
          const prevShare = r.previous / totPrev;
          return { ...r, curShare, prevShare, change: prevShare > 0 ? (curShare - prevShare) / prevShare : null, z: shareZ(r.current, totCur, r.previous, totPrev) };
        })
        .filter((r) => r.z !== null);
      const rising = rows
        .filter((r) => r.current >= R.trend_min_current && (r.z ?? 0) >= R.trend_min_z && (r.change === null || r.change >= R.trend_min_change))
        .sort((a, b) => (b.z ?? 0) - (a.z ?? 0))
        .slice(0, 3);
      const falling = rows
        .filter((r) => r.previous >= R.trend_min_current && (r.z ?? 0) <= -R.trend_min_z && r.change !== null && r.change <= -R.trend_min_change)
        .sort((a, b) => (a.z ?? 0) - (b.z ?? 0))
        .slice(0, 2);
      for (const r of rising) {
        out.push({
          id: `topic-rising-${r.key}`,
          area: "trend",
          severity: "watch",
          kind: "recommendation",
          title: r.previous === 0 ? `"${r.key}" appeared in the latest period` : `"${r.key}" is taking a larger share of tickets`,
          statement: `${fmtInt(r.current)} tickets (${fmtPct(r.curShare)} of all tickets) in the latest ${periods.days} days, versus ${fmtInt(r.previous)} (${fmtPct(r.prevShare)}) in the preceding ${periods.days} days${r.change !== null ? ` — its share rose ${fmtPct(r.change, 0)}` : ""}. The data shows the increase, not its cause.`,
          recommendation: "Read a sample of the recent tickets on this topic to see what changed (schedule, platform, content or communication) and whether a single fix would address them.",
          method,
          evidence: [
            { label: "Latest period", value: `${fmtInt(r.current)} of ${fmtInt(totCur)}` },
            { label: "Preceding period", value: `${fmtInt(r.previous)} of ${fmtInt(totPrev)}` },
            { label: "Statistical strength (z)", value: (r.z ?? 0).toFixed(1) },
          ],
          link: { pathname: "/tickets", overrides: { topics: [r.key] }, label: "Read these tickets" },
        });
      }
      for (const r of falling) {
        out.push({
          id: `topic-falling-${r.key}`,
          area: "trend",
          severity: "info",
          kind: "observation",
          title: `"${r.key}" is taking a smaller share of tickets`,
          statement: `${fmtInt(r.current)} tickets (${fmtPct(r.curShare)}) in the latest ${periods.days} days versus ${fmtInt(r.previous)} (${fmtPct(r.prevShare)}) before — its share fell ${fmtPct(Math.abs(r.change ?? 0), 0)}.`,
          method,
          evidence: [
            { label: "Latest period", value: `${fmtInt(r.current)} of ${fmtInt(totCur)}` },
            { label: "Preceding period", value: `${fmtInt(r.previous)} of ${fmtInt(totPrev)}` },
            { label: "Statistical strength (z)", value: (r.z ?? 0).toFixed(1) },
          ],
          link: { pathname: "/trends", overrides: { topics: [r.key] }, label: "View trend" },
        });
      }
    }
  }

  // 3. Topics with longer resolution ------------------------------------------
  const overallMedian = overall.resolution_median_s;
  if (overallMedian && overallMedian > 0) {
    const slow = input.topics
      .filter((t) => t.resolution_n >= R.slow_topic_min_n && (t.resolution_median_s ?? 0) >= overallMedian * R.slow_topic_factor)
      .sort((a, b) => (b.resolution_median_s ?? 0) * b.resolution_n - (a.resolution_median_s ?? 0) * a.resolution_n)
      .slice(0, 3);
    for (const t of slow) {
      out.push({
        id: `topic-slow-${t.key}`,
        area: "resolution",
        severity: "watch",
        kind: "recommendation",
        title: `"${t.key}" takes longer to resolve`,
        statement: `Median resolution is ${fmtDuration(t.resolution_median_s)} versus ${fmtDuration(overallMedian)} across all tickets in view (${((t.resolution_median_s ?? 0) / overallMedian).toFixed(1)}×), based on ${fmtInt(t.resolution_n)} resolved tickets.`,
        recommendation: "Review how this topic is routed and who resolves it (Support Team page); a longer median often points to a hand-off or an approval step, which the data alone cannot confirm.",
        evidence: [
          { label: "Median resolution", value: fmtDuration(t.resolution_median_s) },
          { label: "90th percentile", value: fmtDuration(t.resolution_p90_s) },
          { label: "Resolved tickets (n)", value: fmtInt(t.resolution_n) },
        ],
        link: { pathname: "/backlog", overrides: { topics: [t.key] }, label: "Resolution detail" },
      });
    }
  }

  // 4. Outstanding issues by project (rate, not only counts) -------------------
  const withOpen = projects.filter((p) => p.open_tickets > 0).sort((a, b) => b.open_breaches - a.open_breaches || b.open_tickets - a.open_tickets);
  if (withOpen.length > 0) {
    const totalOpen = withOpen.reduce((a, p) => a + p.open_tickets, 0);
    const breaches = withOpen.reduce((a, p) => a + p.open_breaches, 0);
    const top = withOpen[0];
    out.push({
      id: "outstanding-projects",
      area: "backlog",
      severity: breaches > 0 ? "attention" : "watch",
      kind: breaches > 0 ? "recommendation" : "observation",
      title: `${fmtInt(totalOpen)} tickets are still unresolved in the latest exports`,
      statement: `${top.label} has the most ${breaches > 0 ? "overdue " : ""}unresolved tickets (${fmtInt(top.open_tickets)}, ${fmtPct(share(top.open_tickets, top.tickets), 2)} of its tickets). ${fmtInt(breaches)} unresolved tickets were older than the resolution threshold at their project's export time.${overall.unclassified_status ? ` Includes ${fmtInt(overall.unclassified_status)} ticket(s) with a status not yet classified as open or closed.` : ""}`,
      recommendation: breaches > 0 ? "Follow up the oldest unresolved tickets first (Backlog page, sorted by age); check whether they are still open in the live system before acting." : undefined,
      evidence: withOpen.map((p) => ({ label: p.label, value: `${fmtInt(p.open_tickets)} open (${fmtPct(share(p.open_tickets, p.tickets), 1)}) · ${fmtInt(p.open_breaches)} over threshold` })),
      link: { pathname: "/backlog", label: "Open backlog" },
    });
  }

  // 5. Dominant themes inside topics (ranked by the number of tickets affected) -
  if (input.topicThemes) {
    const byTopic = new Map<string, { total: number; cells: { col: string; count: number }[] }>();
    for (const c of input.topicThemes.cells) {
      const entry = byTopic.get(c.row) ?? { total: 0, cells: [] };
      entry.total += c.count;
      entry.cells.push({ col: c.col, count: c.count });
      byTopic.set(c.row, entry);
    }
    const found: { weight: number; insight: Insight }[] = [];
    for (const [topic, entry] of byTopic) {
      if (entry.total < R.dominant_theme_min_topic) continue;
      const best = entry.cells.filter((c) => !["no_free_text", "unmatched", "__none__"].includes(c.col)).sort((a, b) => b.count - a.count)[0];
      if (!best) continue;
      const s = share(best.count, entry.total) ?? 0;
      if (s < R.dominant_theme_share) continue;
      const theme = input.subcategoryLabels[best.col] ?? best.col;
      found.push({ weight: best.count, insight: {
        id: `theme-${topic}-${best.col}`,
        area: "recurring",
        severity: "watch",
        kind: "recommendation",
        title: `Most "${topic}" tickets mention ${theme.toLowerCase()}`,
        statement: `${fmtPct(s, 0)} of "${topic}" tickets (${fmtInt(best.count)} of ${fmtInt(entry.total)}) match the "${theme}" keyword rules — a recurring complaint pattern. Keyword matching is indicative, not a verified root cause.`,
        recommendation: `Investigate the "${theme.toLowerCase()}" pattern with the team that owns it; reading a sample of these tickets is the quickest way to confirm what students report.`,
        evidence: [
          { label: "Matching tickets", value: fmtInt(best.count) },
          { label: "Tickets in topic", value: fmtInt(entry.total) },
          { label: "Method", value: "Rule-based keywords (Arabic + English), rules-v1" },
        ],
        link: { pathname: "/topics", overrides: { topics: [topic], subcategories: [best.col] }, label: "Inspect tickets" },
      } });
    }
    // Ranked by the number of tickets affected (not alphabetically).
    out.push(...found.sort((a, b) => b.weight - a.weight || a.insight.id.localeCompare(b.insight.id)).slice(0, 3).map((f) => f.insight));
  }

  // 6. Sessions reported by several students ----------------------------------
  const rec = input.recurring;
  if (rec && rec.summary.recurring_sessions > 0) {
    const top = rec.sessions[0];
    out.push({
      id: "recurring-sessions",
      area: "recurring",
      severity: "info",
      kind: "observation",
      title: `${fmtInt(rec.summary.recurring_sessions)} sessions were reported by ${rec.summary.min_students}+ different students`,
      statement: `These sessions account for ${fmtInt(rec.summary.tickets_in_recurring_sessions)} tickets. The most reported is session ${top.session_ref}${top.lesson_name ? ` (${top.lesson_name})` : ""} with ${fmtInt(top.tickets)} tickets from ${fmtInt(top.students)} students.`,
      evidence: rec.sessions.slice(0, 5).map((s) => ({ label: `Session ${s.session_ref} · ${names[s.project_code] ?? s.project_code}`, value: `${s.students} students, ${s.tickets} tickets` })),
      link: { pathname: "/topics", label: "See recurring sessions", hash: "recurring" },
    });
  }

  // 6b. Lessons referenced by many different students ---------------------------
  const lessons = (input.lessons ?? []).filter((l) => l.key !== "__none__" && l.unique_owners >= R.lesson_min_students);
  if (lessons.length > 0) {
    const top = [...lessons].sort((a, b) => b.unique_owners - a.unique_owners).slice(0, 5);
    out.push({
      id: "lesson-hotspots",
      area: "recurring",
      severity: "info",
      kind: "recommendation",
      title: `Lesson "${top[0].key}" is referenced by the most students`,
      statement: `${fmtInt(top[0].unique_owners)} different students raised ${fmtInt(top[0].tickets)} tickets about sessions of this lesson.`,
      recommendation: "Consider a content or delivery review of the lessons listed; the ticket topics show what was reported.",
      evidence: top.map((l) => ({ label: l.key, value: `${fmtInt(l.unique_owners)} students · ${fmtInt(l.tickets)} tickets` })),
      link: { pathname: "/tickets", overrides: { lesson: top[0].key }, label: "Read these tickets" },
    });
  }

  // 7. Unusual days, detected per project ----------------------------------------
  if (input.spikes.length > 0) {
    const top = [...input.spikes].sort((a, b) => b.score - a.score).slice(0, 5);
    const projectsWithSpikes = new Set(input.spikes.map((s) => s.project)).size;
    out.push({
      id: "volume-spikes",
      area: "trend",
      severity: "watch",
      kind: "recommendation",
      title: `${input.spikes.length} unusually busy day(s) in ${projectsWithSpikes} project(s)`,
      statement: "On these days a project received far more tickets than its own recent baseline. The data does not show why.",
      recommendation: "Check for platform incidents, deadlines, schedule changes or announcements on these dates for the projects listed.",
      method: `Each project is compared with its own trailing ${R.spike_window_days}-day median (robust z ≥ ${R.spike_threshold}, at least ${R.spike_min_count} tickets). The first ${R.spike_rampup_days} days after a project's first ticket are excluded, so an intake launch is not reported as an incident.`,
      evidence: top.map((s) => ({ label: `${fmtCalendarDate(s.date)} · ${names[s.project] ?? s.project}`, value: `${fmtInt(s.count)} tickets (typical ≈ ${fmtInt(s.baseline)})` })),
      link: { pathname: "/trends", extra: { grain: "day", split: "project" }, label: "Daily trend by project" },
    });
  }

  // 8. Threshold breaches (rates per project) ------------------------------------
  const breachRate = share(overall.resolution_breaches, overall.resolution_n);
  if (breachRate !== null) {
    const worst = projects
      .filter((p) => p.resolution_n > 0)
      .map((p) => ({ p, rate: share(p.resolution_breaches, p.resolution_n) ?? 0 }))
      .sort((a, b) => b.rate - a.rate);
    out.push({
      id: "resolution-threshold",
      area: "resolution",
      severity: breachRate > R.breach_attention_rate ? "attention" : breachRate > R.breach_watch_rate ? "watch" : "info",
      kind: "observation",
      title: `${fmtPct(breachRate, 0)} of resolved tickets exceeded the ${fmtDuration(input.thresholds.resolution_seconds)} resolution threshold`,
      statement: `The threshold is an illustrative monitoring value (configurable in Settings), not a contractual SLA.${worst[0] ? ` Highest breach rate: ${worst[0].p.label} (${fmtPct(worst[0].rate, 0)}).` : ""}`,
      evidence: worst.map(({ p, rate }) => ({ label: p.label, value: `${fmtPct(rate, 0)} of ${fmtInt(p.resolution_n)}` })),
      link: { pathname: "/backlog", label: "Threshold analysis" },
    });
  }

  // 9. Recorded response caveat -------------------------------------------------
  const genericShare = share(overall.generic_ack, overall.tickets);
  if (genericShare !== null && genericShare > R.generic_ack_caveat_share) {
    out.push({
      id: "response-caveat",
      area: "data",
      severity: "info",
      kind: "caveat",
      title: "Recorded response times are not proof of a human reply",
      statement: `${fmtPct(genericShare, 1)} of tickets carry a templated acknowledgement as their response text, and ${fmtInt(overall.tickets - overall.with_response_ts)} tickets have no response timestamp. Treat "recorded first response" metrics as system timestamps.`,
      evidence: [
        { label: "Generic acknowledgements", value: fmtInt(overall.generic_ack) },
        { label: "Response timestamp recorded", value: fmtPct(share(overall.with_response_ts, overall.tickets)) },
        { label: `Tickets with status "${statusLabel(null)}"`, value: fmtInt(overall.missing_status) },
      ],
      link: { pathname: "/data-quality", label: "Data quality" },
    });
  }

  return out.sort(byPriority);
}

function byPriority(a: Insight, b: Insight): number {
  return ORDER[a.severity] - ORDER[b.severity] || KIND_ORDER[a.kind] - KIND_ORDER[b.kind];
}

/** Caveats about the data itself: outdated exports, partial imports, unmapped values, empty projects. */
function dataCaveats(input: InsightInputs, R: InsightRules, names: Record<string, string>): Insight[] {
  const h = input.health;
  if (!h) return [];
  const out: Insight[] = [];
  const name = (code: string) => names[code] ?? h.coverage.find((c) => c.project === code)?.name ?? code;

  const dated = h.coverage.filter((c) => c.snapshot_at && c.tickets > 0);
  if (dated.length > 1) {
    const newest = Math.max(...dated.map((c) => Date.parse(c.snapshot_at!)));
    const stale = dated
      .map((c) => ({ c, days: Math.floor((newest - Date.parse(c.snapshot_at!)) / 86_400_000) }))
      .filter((x) => x.days >= R.stale_export_days)
      .sort((a, b) => b.days - a.days);
    if (stale.length > 0) {
      out.push({
        id: "stale-exports",
        area: "data",
        severity: "watch",
        kind: "caveat",
        title: `${stale.length} project export${stale.length === 1 ? " is" : "s are"} older than the others`,
        statement: `${stale.map((x) => `${name(x.c.project)} ends ${fmtDate(x.c.snapshot_at)} (${x.days} days earlier)`).join("; ")}. Recent days are missing for ${stale.length === 1 ? "this project" : "these projects"}, so totals for recent periods understate them. Trend insights compare each project only within its own data.`,
        recommendation: "Import a newer export for these projects (Settings & Imports → Add / update).",
        evidence: dated
          .sort((a, b) => Date.parse(b.snapshot_at!) - Date.parse(a.snapshot_at!))
          .map((c) => ({ label: name(c.project), value: `data as of ${fmtDate(c.snapshot_at)}` })),
        link: { pathname: "/data-quality", label: "Data coverage" },
      });
    }
  }

  for (const imp of h.activeImports) {
    out.push({
      id: `import-running-${imp.project}`,
      area: "data",
      severity: "attention",
      kind: "caveat",
      title: `An import is in progress for ${name(imp.project)}`,
      statement: `${fmtInt(imp.rows_applied)} of ${fmtInt(imp.rows_to_apply)} rows have been applied. Figures for this project are incomplete until it finishes; insights update automatically afterwards.`,
      evidence: [{ label: "Started", value: fmtDate(imp.started_at) }],
    });
  }
  for (const p of h.partialImports) {
    out.push({
      id: `import-partial-${p.project}`,
      area: "data",
      severity: "attention",
      kind: "caveat",
      title: `The last import for ${name(p.project)} stopped part-way`,
      statement: `${fmtInt(p.rows_applied)} of ${fmtInt(p.rows_to_apply)} rows were applied before it stopped. The project mixes the previous export with part of the new one until the import is retried.`,
      recommendation: "An administrator can resume it from Settings & Imports (Retry) — already applied rows are not duplicated.",
      evidence: [{ label: "Rows applied", value: `${fmtInt(p.rows_applied)} / ${fmtInt(p.rows_to_apply)}` }],
      link: { pathname: "/data-quality", label: "Import health" },
    });
  }
  const rejected = h.rejectedRows.filter((r) => r.rejected > 0);
  if (rejected.length > 0) {
    out.push({
      id: "rejected-rows",
      area: "data",
      severity: "info",
      kind: "caveat",
      title: `${fmtInt(rejected.reduce((a, r) => a + r.rejected, 0))} row(s) were rejected in the latest imports`,
      statement: "Rejected rows are not in the figures. Each rejection is recorded with its reason in the import report.",
      evidence: rejected.map((r) => ({ label: name(r.project), value: `${fmtInt(r.rejected)} rejected · ${r.source_filename}` })),
      link: { pathname: "/data-quality", label: "Import reports" },
    });
  }
  if (h.unmappedTopics > 0) {
    out.push({
      id: "unmapped-topics",
      area: "data",
      severity: "watch",
      kind: "caveat",
      title: `${fmtInt(h.unmappedTopics)} topic${h.unmappedTopics === 1 ? " is" : "s are"} not mapped to a category`,
      statement: "Their tickets are counted as \"Uncategorized\" in category views until an administrator maps them.",
      recommendation: "Map the new topics in Settings & Imports → Categories; category figures update immediately.",
      evidence: [{ label: "Unmapped topics", value: fmtInt(h.unmappedTopics) }],
      link: { pathname: "/settings", extra: { tab: "categories" }, label: "Map topics" },
    });
  }
  if (h.unclassifiedStatusTickets > 0) {
    out.push({
      id: "unclassified-statuses",
      area: "data",
      severity: "watch",
      kind: "caveat",
      title: `${fmtInt(h.unclassifiedStatusTickets)} ticket(s) have a status that is not classified as open or closed`,
      statement: "They are counted as open in backlog figures, so they are never hidden, but the backlog may be overstated until the status is classified.",
      recommendation: "Classify the new status values in Settings & Imports → Categories.",
      evidence: [{ label: "Tickets", value: fmtInt(h.unclassifiedStatusTickets) }],
      link: { pathname: "/settings", extra: { tab: "categories" }, label: "Classify statuses" },
    });
  }
  const empty = h.coverage.filter((c) => c.tickets === 0);
  if (empty.length > 0) {
    out.push({
      id: "empty-projects",
      area: "data",
      severity: "info",
      kind: "caveat",
      title: `${empty.length} project${empty.length === 1 ? " has" : "s have"} no imported tickets yet`,
      statement: `${empty.map((c) => c.name).join(", ")} ${empty.length === 1 ? "is" : "are"} included in this view but contribute${empty.length === 1 ? "s" : ""} no data until an export is imported.`,
      evidence: empty.map((c) => ({ label: c.name, value: "0 tickets" })),
    });
  }
  return out;
}
